	public PricingPlan removeFromFeeSchedules( UUID parentId, FeeSchedule removeFrom ) {
	    LOGGER.info("handling RemoveFeeSchedulesFromPricingPlanEvent " );
	
	    PricingPlan parentEntity = repository.findById(parentId).get();
	    FeeSchedule child = registry.project( FeeSchedule.class, removeFrom.getFeeScheduleId());
	    
	    parentEntity.getFeeSchedules().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

